from scipy.optimize import least_squares
fams={
'F1 A-shift pos': lambda p,t,A: -p[0]*t**p[1]*A**p[2]*np.exp(-p[3]*A) + p[4]*t**p[5]*(A-p[6])*np.exp(-p[7]*t) + p[8]*A*t**p[9],
'F2 LH neg': lambda p,t,A: -p[0]*t**p[1]*A**p[2]/(1+p[3]*A) + p[4]*t**p[5]*A**p[6]*np.exp(-p[7]*t) + p[8]*A*t**p[9],
'F3 no At': lambda p,t,A: -p[0]*t**p[1]*A**p[2]*np.exp(-p[3]*A) + p[4]*t**p[5]*A**p[6]*np.exp(-p[7]*t) + p[8]*t**p[9],
}
for k,f in fams.items():
    best=None
    for s in range(30):
        p0=np.random.RandomState(s).uniform(-0.5,1.5,10)
        try:
            r=least_squares(lambda p: f(p,t,A)-dA_dt, p0, bounds=(-30,30), max_nfev=3000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
